/* 背景 */
.chat-detail-screen {
  background-image: url('https://s3.bmp.ovh/2026/08/21/7IwO20zJ.png') !important; /* 整体聊天背景图 */
  background-size: cover !important; /* 铺满方式 */
  background-position: center !important; /* 对齐位置 */
  background-repeat: no-repeat !important; /* 平铺模式 */
}

:root {
  /* 消息间时间戳 */
  --timestamp-color: #564243; /* 时间戳颜色 */

  /* IG/QQ 风格已读状态 */
  --status-color: #564243; /* 已读/送达默认颜色 */
  --status-read-color: #564243; /* 「已读」颜色 */
  --status-sent-color: #564243; /* 「已送达」颜色 */

  /* WhatsApp 气泡内时间+勾勾 */
  --wa-me-meta-color: #564243; /* 我方气泡内时间颜色 */
  --wa-them-meta-color: #564243; /* 对方气泡内时间颜色 */
  --wa-me-check-color: #564243; /* 我方已读勾勾颜色 */
}

/* 旁白 */
:root {
  --narration-color: #564243; /* 旁白默认颜色 */
}

.msg-narration-custom {
  color: #564243 !important; /* 旁白消息文本颜色 */
}

/* 旁白模式 */
.input-sendas-narration-bar {
  background: #fef7fb !important; /* 输入条背景色 */
  color: #564243 !important; /* 输入条文字颜色 */
  border-radius: 4px !important; /* 输入条圆角 */
}

.input-sendas-narration-bar .input-sendas-label {
  color: #564243 !important; /* 标签文字颜色 */
}

.input-sendas-narration-bar .input-sendas-close {
  color: #564243 !important; /* 关闭按钮颜色 */
}

/* 顶栏整体 */
.chat-header-custom {
  background-image: url('https://s3.bmp.ovh/2026/08/21/74xBUnXX.png') !important; /* 顶栏背景图 */
  background-size: cover !important; /* 背景缩放 */
  background-position: 50% 95% !important; /* 背景偏移位置 */
  background-repeat: no-repeat !important; /* 平铺模式 */
  backdrop-filter: none !important; /* 高斯模糊 */
  -webkit-backdrop-filter: none !important; /* Safari 模糊 */
  box-shadow: none !important; /* 阴影 */
  height: 100px !important; /* 固定高度 */
  min-height: 100px !important; /* 最小高度 */
  max-height: 100px !important; /* 最大高度 */
   border: none !important; /* 边框 */
}

/* 隐藏语音 / 视频按钮 */
.header-btn-phone,
.header-btn-video {
  opacity: 0 !important; /* 透明度：0 隐藏，1 显示 */
}

/* 隐藏头像（含占位） */
.header-avatar-container,
.chat-header-avatar {
  display: none !important; /* 显示状态 */
  width: 0 !important; /* 宽度 */
  height: 0 !important; /* 高度 */
  margin: 0 !important; /* 外边距 */
  padding: 0 !important; /* 内边距 */
  overflow: hidden !important; /* 溢出隐藏 */
  opacity: 0 !important; /* 透明度 */
}

/* 头像父容器去掉间距 */
.header-profile-section {
  gap: 0 !important; /* 子元素间距 */
  padding-left: 0 !important; /* 左内边距 */
  margin-left: 0 !important; /* 左外边距 */
}

/* 名字 */
.chat-header-title {
  position: relative !important; /* 定位模式 */
  display: inline-flex !important; /* 布局模式 */
  align-items: center !important; /* 垂直对齐 */
  color: #d09b4a !important; /* 名字颜色 */
  margin-left: -8px !important; /* 左外边距 */
  transform: translateX(0px) !important; /* 水平微调 */
}

/* 名字后面的 URL 图 */
.chat-header-title::after {
  content: "" !important; /* 保留，用于生成伪元素 */
  display: inline-block !important; /* 块级类型 */
  width: 130px !important; /* 图标宽度 */
  height: 130px !important; /* 图标高度 */
  margin-left: -5px !important; /* 与名字的水平间距 */
  background: url("https://s3.bmp.ovh/2026/09/21/UNnMLnE7.png") no-repeat center/contain !important; /* 小图标背景图 */
  flex-shrink: 0 !important; /* 弹性缩放 */
  pointer-events: none !important; /* 点击穿透 */
  vertical-align: middle !important; /* 垂直对齐 */
  transform: translateY(-1px) !important; /* 垂直微调 */
}

/* 返回 / 更多设置按钮 */
.header-btn-back,
.header-btn-info,
.header-action-btn {
  color: #564243 !important; /* 按钮颜色 */
}

/* 对方文字气泡 */
.bubble-them-custom {
  background: transparent !important; /* 背景色 */
  box-shadow: none !important; /* 阴影 */
  border-radius: 0 !important; /* 圆角 */
  border-style: solid !important; /* 边框样式 */
  border-color: transparent !important; /* 边框颜色 */
  border-image: url("https://s3.bmp.ovh/2026/09/23/gGxAZJIr.png") 240 240 240 220 fill / 24px stretch !important; /* 九宫格切图气泡 */
  border-width: 8px 10px !important; /* 九宫格边框厚度 */
  color: #564243 !important; /* 文字颜色 */
  position: relative !important; /* 定位模式 */
  padding: 5px 5px 5px 12px !important; /* 内边距（上右下左） */
  margin-top: 2px !important; /* 上外边距 */
  transform: translateX(-5px) !important; /* 水平微调 */
}

/* 我方文字气泡 */
.bubble-me-custom {
  background: transparent !important; /* 背景色 */
  box-shadow: none !important; /* 阴影 */
  border-radius: 0 !important; /* 圆角 */
  border-style: solid !important; /* 边框样式 */
  border-color: transparent !important; /* 边框颜色 */
  border-image: url("https://s3.bmp.ovh/2026/08/21/iV8EmHQQ.png") 240 220 240 240 fill / 24px stretch !important; /* 九宫格切图气泡 */
  border-width: 10px 10px !important; /* 九宫格边框厚度 */
  color: #564243 !important; /* 文字颜色 */
  position: relative !important; /* 定位模式 */
  padding: 7px 10px 5px 6px !important; /* 内边距（上右下左） */
  margin-top: 2px !important;  /* 上外边距 */
  transform: translateX(5px) !important; /* 水平微调 */
}

/* 特殊消息去气泡外壳（图片/卡片等） */
.bubble-me-custom.no-padding,
.bubble-them-custom.no-padding,
.bubble-me-custom.msg-radius-media,
.bubble-them-custom.msg-radius-media {
  background: transparent !important; /* 清除背景色 */
  background-image: none !important; /* 清除背景图 */
  border: none !important; /* 清除边框 */
  box-shadow: none !important; /* 清除阴影 */
  border-image: none !important; /* 清除九宫格边框 */
  border-radius: 0 !important; /* 清除圆角 */
  padding: 0 !important; /* 清除内边距 */
  -webkit-backdrop-filter: none !important; /* 清除 Safari 背景滤镜 */
  backdrop-filter: none !important; /* 清除背景滤镜 */
  text-shadow: none !important; /* 清除文字阴影 */
  min-width: 0 !important; /* 取消最小宽度 */
  transform: none !important; /* 取消平移偏移 */
}

/* ============================================================
   3. 头像挂件
   ============================================================ */

.msg-avatar-them-container,
.msg-avatar-me-container {
  position: relative !important; /* 相对定位（挂件锚点） */
  overflow: visible !important; /* 溢出显示 */
}

.msg-avatar-them-container::after,
.msg-avatar-me-container::after {
  content: "" !important; /* 保留，用于生成挂件 */
  position: absolute !important; /* 绝对定位 */
  width: 70px !important; /* 挂件宽度 */
  height: 70px !important; /* 挂件高度 */
  background: url("https://s3.bmp.ovh/2026/08/26/VgvgGupR.png") no-repeat center/contain !important; /* 挂件图片 */
  top: -15px !important; /* 垂直位置 */
  right: -10px !important; /* 水平位置 */
  pointer-events: none !important; /* 点击穿透 */
  z-index: 10 !important; /* 堆叠层级 */
}

/* 底栏 */
.chat-input-area-root {
  background-image: url('https://s3.bmp.ovh/2026/08/21/WtItIHcM.png') !important; /* 底栏背景图 */
  background-size: cover !important; /* 铺满方式 */
  background-position: center !important; /* 居中 */
  background-repeat: no-repeat !important; /* 不重复 */
}

/* 输入框外层 */
.input-row-wrapper {
  position: relative !important; /* 定位模式 */
  display: flex !important; /* 布局模式 */
  flex-wrap: wrap !important; /* 换行规则 */
  align-items: center !important; /* 垂直对齐 */
  justify-content: space-around !important; /* 水平分布 */
  row-gap: 8px !important; /* 行间距 */
  column-gap: 0 !important; /* 列间距 */
  padding: 0 !important; /* 内边距 */
  background: transparent !important; /* 背景色 */
  border: none !important; /* 边框 */
  overflow: visible !important; /* 溢出显示 */
}

/* 中间两层容器溶解，按钮直接参与外层排版 */
.input-action-bar-custom,
.input-btns-right {
  display: contents !important; /* 溶解容器，子按钮参与外层 Flex */
}

/* 发送 / 停止 */
.send-btn-custom,
.stop-btn-custom {
  position: absolute !important; /* 绝对定位 */
  right: 10px !important; /* 靠右边距 */
  top: 11px !important; /* 靠上边距 */
  z-index: 2 !important; /* 堆叠层级 */
}

/* 底栏按钮 */
.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai {
  background: transparent !important; /* 按钮背景：透明 */
  margin-left: 0 !important; /* 左外边距 */
}

/* 输入框 */
#chat-message-input {
  order: -1 !important; /* 排列顺序：置顶 */
  flex: 0 0 100% !important; /* 弹性占比：独占一行 */
  width: 100% !important; /* 宽度 */
  box-sizing: border-box !important; /* 盒模型计算方式 */
  border-image: url("https://s3.bmp.ovh/2026/08/21/F5EJlAPI.png") 100 90 90 90 fill / 15px stretch !important; /* 九宫格背景图 */
  border-style: solid !important; /* 边框样式 */
  border-color: transparent !important; /* 边框颜色 */
  border-width: 10px 15px !important; /* 九宫格边框厚度 */
  min-height: 54px !important;  /* 最小高度 */
  max-height: 120px !important;  /* 最大高度 */
  padding: 8px 45px 9px 8px !important; /* 内边距（上右下左） */
  font-size: 15px !important; /* 字号 */
  line-height: 20px !important; /* 行高 */
  overflow-y: auto !important; /* 垂直滚动条 */
  overflow-x: hidden !important; /* 禁止水平滚动 */
  white-space: pre-wrap !important; /* 保留空格与换行 */
  word-break: break-all !important; /* 断字规则 */
  background: transparent !important; /* 底色 */
  border-radius: 0 !important; /* 圆角 */
}

/* 输入框颜色 */
.input-row-wrapper #chat-message-input,
.input-row-wrapper #chat-message-input:focus,
.input-row-wrapper #chat-message-input:focus-visible,
.input-row-wrapper #chat-message-input:active {
  background: transparent !important; /* 各状态保持透明背景 */
  border-radius: 0 !important; /* 各状态保持无圆角 */
  outline: none !important; /* 消除聚焦轮廓线 */
  box-shadow: none !important; /* 消除聚焦阴影 */
  color: #564243 !important; /* 键入文字颜色 */
  -webkit-text-fill-color: #564243 !important; /* Webkit 文字填充颜色 */
  caret-color: #564243 !important; /* 光标颜色 */
}

/* 占位符隐藏 */
.input-box-custom::placeholder,
.input-box-custom textarea::placeholder {
  color: transparent !important; /* 占位符颜色 */
  -webkit-text-fill-color: transparent !important; /* Webkit 占位符颜色 */
  opacity: 0 !important; /* 透明度 */
}

/* 第二行背景图：铺在按钮后面 */
.input-row-wrapper::after {
  content: "" !important; /* 保留，用于生成底部背景层 */
  position: absolute !important; /* 绝对定位 */
  left: 0 !important; /* 靠左距离 */
  right: 0 !important; /* 靠右距离 */
  bottom: 7px !important; /* 靠底距离 */
  height: 40px !important; /* 背景图高度 */
  background: url("https://s3.bmp.ovh/2026/09/23/zX2dipw0.png") no-repeat center / 125%  !important; /* 装饰背景图 */
  pointer-events: none !important; /* 点击穿透 */
  z-index: 0 !important; /* 堆叠层级 */
}

/* 按钮浮在背景图上面 */
.input-btn-mic,
.input-btn-ai,
.input-btn-sticker,
.input-btn-plus {
  position: relative !important; /* 相对定位 */
  z-index: 1 !important; /* 堆叠层级 */
}

/* 输入框排最前，独占第一行；按钮按原顺序自动排到第二行 */
.input-row-wrapper #chat-message-input {
  order: -1 !important; /* 排序位置：置顶 */
}

/* 第二行靠左起排，之后每个按钮单独用 left 移动 */
.input-row-wrapper {
  justify-content: flex-start !important; /* 主轴对齐：左对齐 */
}

.input-btn-plus,
.input-btn-mic,
.input-btn-ai,
.input-btn-sticker {
  position: relative !important; /* 相对定位 */
  z-index: 1 !important; /* 堆叠层级 */
}

/* 发送图标颜色 */
.input-row-wrapper .send-btn-custom,
.input-row-wrapper .send-btn-custom svg,
.input-row-wrapper .send-btn-custom svg * {
  color: #564243 !important; /* 图标填充颜色 */
  stroke: #564243 !important; /* SVG 描边颜色 */
}

.nuo-console-shell {
  /* 「查看控制台」文字 */
  --console-toggle-color: #564243; /* 开关按钮文本颜色 */
  --console-toggle-bg: #fef7fb !important; /* 开关按钮背景色 */

  /* token 按钮 */
  --console-token-bg: #fef7fb !important;  /* Token 按钮背景色 */
  --console-token-shadow: none; /* Token 按钮阴影 */
  --console-token-color: #564243; /* Token 按钮文本颜色 */
}

.nuo-console-toggle-btn,
.nuo-console-token-btn {
  border-radius: 4px !important; /* 圆角 */
  border: 1px solid #e6e6e6 !important; /* 边框 */
}

/* 隐藏但保留可点击 */
.input-btn-plus,  
.input-btn-mic,  
.input-btn-ai,  
.input-btn-sticker {
  opacity: 0 !important; /* 透明度：0 隐藏外观，1 显示 */
  pointer-events: auto !important; /* 鼠标响应 */
  transform: translateY(-5px) !important;   /* 垂直平移偏移 */
}

/* 左右移动：变小往右，变大往左 */
.input-btn-plus    { left: 390px !important; } /* 更多 */ /* 左偏移距离 */
.input-btn-mic     { left: -30px !important; }  /* 麦克风 */ /* 左偏移距离 */
.input-btn-ai      { left: 130px !important; }  /* 回复 */ /* 左偏移距离 */
.input-btn-sticker { left: 240px !important; }  /* 表情包 */ /* 左偏移距离 */
